insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('guest_gate', 'Guest shell gate', 'cloudflare', 2, 4, 'worker', 'live', 'Worker that checks the human check and the limits, then opens a terminal.');
