insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_hub', 'Hub MCP', 'gcp', 2, 1, 'service', 'live', 'Read-only tool server for AI assistants: links, status, public chain and data, commands.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_standby', 'Standby website', 'gcp', 2, 2, 'service', 'live', 'A copy of rabbitsoftware.io on Cloud Run, ready if Pages is down.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_rfnexus', 'RF Nexus preview', 'gcp', 2, 3, 'service', 'live', 'A static export of the RF Nexus interface on Cloud Run. No backend: API calls answer 503. Not part of RabbitOS.');
