insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_shell', 'Visitor shell', 'gcp', 3, 1, 'service', 'live', 'Cloud Run: one throwaway terminal per guest, with claude, gemini, copilot and common languages.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_proxy', 'Allowlist proxy', 'gcp', 3, 2, 'vm', 'live', 'The only way out of the visitor shell: 13 named hosts, nothing else.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_mirror', 'App mirror', 'gcp', 3, 3, 'service', 'live', 'A read copy of the console on Cloud Run (run.rabbitsoftware.io).');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_status_job', 'Status recorder', 'gcp', 3, 4, 'job', 'live', 'Cloud Run job, every 5 minutes: checks the public services and writes the feed.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_qa', 'Weekly audit', 'gcp', 3, 5, 'job', 'live', 'Scheduler, Workflow and Cloud Run job: crawls both sites and writes a report with maps.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_backup_job', 'Cloud backup job', 'gcp', 3, 8, 'job', 'live', 'Cloud Run job rabbit-backup: Supabase dump and Cloudflare D1, KV, R2 into the private bucket, nightly. Written and tested; waiting for you to set it up.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_miner_job', 'Cloud miner', 'gcp', 3, 9, 'job', 'live', 'Cloud Run job rabbit-miner: mines the rabbit web snapshot onto the Maxwell chain nightly (05:00), mirrors it to the app first, then publishes the chain. Mined block 3.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('obsidian_vault', 'Obsidian vault', 'owner', 4, 4, 'data', 'live', 'Notes, agent files and docs on the owner''s PC. Linked folders (the whole PC) stay out of every copy.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_vault_bucket', 'Vault copy (private)', 'gcp', 4, 6, 'storage', 'live', 'Private, versioned bucket: the vault set, uploaded hourly. Nothing else can read it.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_anchor_job', 'Bitcoin anchor job', 'gcp', 3, 10, 'job', 'live', 'Cloud Run job rabbit-anchor: OpenTimestamps proofs of the ledger and Maxwell chain heads, every 6 hours when they changed.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_anchor_chains_job', 'Ethereum and XRPL anchor job', 'gcp', 3, 11, 'job', 'planned', 'Cloud Run job rabbit-anchor-chains: posts the anchor fingerprint to Ethereum and the XRP Ledger. Deployed and tested; its schedule is paused until the two fee accounts are funded.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('bitcoin_network', 'Bitcoin (OpenTimestamps)', 'external', 3, 2, 'external', 'live', 'Public calendars batch the digests into Bitcoin transactions; the proofs are upgraded when a block confirms.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_kms_wallet', 'Wallet key (Cloud KMS HSM)', 'gcp', 4, 7, 'service', 'live', 'One secp256k1 key in a hardware module: the Bitcoin and Ethereum donation addresses come from its public half. The private key cannot leave. Donations are open: the front page, /donate and the app show the addresses with open-in-wallet links.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_wallet_watch', 'Wallet watcher', 'gcp', 3, 12, 'job', 'live', 'Cloud Run job rabbit-wallet-watch every 30 minutes: reads the wallet addresses from public networks, keeps a private record of what arrived, and emails the owner. No signing permission.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_vault_mirror', 'Vault mirror job', 'gcp', 3, 13, 'job', 'planned', 'Cloud Run job rabbit-vault-mirror: clones the vault repository from GitHub every hour into the private vault bucket. Written and tested; waiting for the read-only GitHub token (step 1).');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('github_vault', 'Vault repository (GitHub, private)', 'external', 4, 9, 'storage', 'live', 'therealsickonechase-bit/obsidian-rabbitos-vault: every note, pushed from the PC every 30 minutes. Private; never public.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_vault_search', 'Vault search (Vertex AI Search)', 'gcp', 3, 14, 'service', 'live', 'Search over the private vault copy, re-indexed daily. Owner only, through the owner''s own sign-in.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('hf_space', 'Image Space (Hugging Face)', 'external', 3, 15, 'service', 'live', 'rabbitos-eeg-qwen-image on ZeroGPU: draws an image from fixed words. Receives words only, never numbers, titles, notes or raw signals.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('hf_model', 'RabbitSoftware model (Hugging Face)', 'external', 3, 16, 'service', 'live', 'Llama-3.2-3B-RabbitSoftware-GGUF: LoRA fine-tune of Llama 3.2 3B Instruct in GGUF. Public.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('hf_storage', 'Datasets and buckets (Hugging Face)', 'external', 4, 10, 'storage', 'live', 'Three datasets (two private) and four buckets (RabbitAI is 1.7 GB). Backed up to Google Cloud every night from the owner''s PC.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_research_agent', 'Research Agent (A2A)', 'gcp', 2, 4, 'service', 'live', 'Cloud Run rabbit-research-agent: answers the A2A protocol with live read-only searches of PubMed, Europe PMC, ClinicalTrials.gov and openFDA. Stores nothing, no secrets, no roles.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_agent_registry', 'Agent Registry', 'gcp', 2, 5, 'service', 'live', 'Google Cloud Agent Registry: lists the Research Agent and the Hub MCP so they can be found and called. Describes, does not grant access.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_task_worker', 'Task worker (Cloud Run job)', 'gcp', 3, 16, 'job', 'live', 'rabbit-task-worker every 5 minutes: claims one approved task from the RabbitOS queue, runs it on public sources only and sends back a proposal for the owner to approve. Moved from the PC; reads only the ingest secret.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_kms_anchor', 'Anchoring key (Cloud KMS HSM)', 'gcp', 4, 8, 'service', 'live', 'A second hardware key, separate from the donation key, that signs the Ethereum and XRP Ledger anchor transactions. It is meant to hold only fee money.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_vertex', 'Vertex AI (Gemini)', 'gcp', 3, 6, 'service', 'live', 'The Gemini model that assistants on the owner''s computer use.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('gcp_k8s', 'Kubernetes cluster', 'gcp', 3, 7, 'service', 'optional', 'Not created. A script is ready if it is ever wanted.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('research_agents', 'Research agents', 'owner', 3, 1, 'agent', 'live', 'Python agents that find public research and sync it through a signed ingest.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('daily_backup', 'Daily backup job', 'owner', 3, 2, 'job', 'live', 'Windows scheduled task at 3:00 AM: miner, chain mirror, backups.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('vault_agent', 'Vault agent', 'owner', 3, 3, 'agent', 'live', 'Runs approved jobs on the owner''s vault. Owner only.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('allowed_internet', 'Allowed internet', 'external', 3, 1, 'external', 'live', 'Package registries, GitHub, the model APIs and the public RabbitOS app.');
insert into public.platform_nodes (id, label, provider, lane, sort_order, kind, status, about) values ('supabase', 'Database', 'supabase', 4, 1, 'database', 'live', 'Supabase Postgres: 29 tables, row-level security on every table; the system of record.');
