insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-shell-gcp', 'Guest shell runs on Google Cloud', 'done', 'Google Cloud', 'Throwaway terminal per visitor behind an allowlist proxy; tested end to end.', 0);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-hub', 'Hub MCP with guest and owner commands', 'done', 'Assistants', 'Read-only tools, safe command drafting, agents and languages listed honestly.', 1);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-agents-cli', 'claude, gemini and copilot verified in both shell images', 'done', 'Assistants', 'The build now fails if any of the three cannot run.', 2);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-standby', 'Standby website on Cloud Run', 'done', 'Google Cloud', 'Refreshed by re-running Setup-GcpStandby.ps1.', 3);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-obs', 'Logging, metrics, alerts, dashboard and BigQuery analytics', 'done', 'Google Cloud', 'Five alert policies; no visitor IP addresses are stored.', 4);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-proxy', 'Proxy VM on a least-privilege account', 'done', 'Google Cloud', 'It can only write logs and metrics.', 5);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-status', 'Live status feed and status page', 'done', 'Website', 'Updates every 5 minutes; goes stale visibly; alert if the recorder stops.', 6);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-audit', 'Weekly audit with score, fixes and maps', 'done', 'Google Cloud', 'Mondays 09:00 Los Angeles time; reports kept 180 days.', 7);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-miner', 'Rabbit web data miner on the Maxwell chain', 'done', 'Chain', 'Block 2 mined; the daily job runs it from the next 3:00 AM run.', 8);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-supabase-tree', 'Supabase tree, checked against the live database', 'done', 'Supabase', '29 tables; the 8 closed ones refuse an anonymous reader.', 9);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-browser-test', 'Try the guest shell in a browser', 'waiting', 'You', 'Needs the human check, which only a person can pass.', 10);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-sql', 'Platform-graph tables and data applied in Supabase (2026-10-15)', 'done', 'Supabase', '55 nodes, 89 connections, 49 roadmap items. Row-level security on; everyone can read, only the service role can write.', 11);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-push', 'Push the local commits to GitHub', 'waiting', 'You', 'All three repositories have commits that exist only on this computer.', 12);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-app-deploy', 'RabbitOS app deployed (2026-10-15)', 'done', 'RabbitOS', 'Ships the guest shell prompt box and key toggle, the command catalog page, enforced content-security-policy on 17 more pages, and hides the paused Donate card, link and page.', 13);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-owner-key', 'Create a hub key and test the owner role', 'waiting', 'You', 'Run New-HubKey.ps1; the key goes to the clipboard and is never printed.', 14);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-credits', 'Check the Google Cloud credit balance and its terms', 'waiting', 'You', 'It cannot be read from here.', 15);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-relink', 'Relink the local audit chain', 'waiting', 'You', 'From the 2026-10-09 notes: python .\relink_audit_once.py, then python .\rabbit_sync.py. May already be done.', 16);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-contact-key', 'Back up the contact-records private key offline, in two places', 'waiting', 'You', 'From the 2026-10-09 notes; before opening sign-ups.', 17);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-privacy', 'Update privacy.html', 'waiting', 'You', 'Draft in docs/privacy-page-change.md; has decisions only you can make.', 18);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-titles', 'Give every RabbitOS page its own title', 'next', 'Audit', '38 pages share a title; the app''s pages are all just ''RabbitOS''.', 19);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-descriptions', 'Add meta descriptions to 5 website pages', 'next', 'Audit', 'local, agent, license, recovery, dna-code.', 20);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-h1', 'Add a main heading to /downloads in the app', 'next', 'Audit', '', 21);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-csp', 'Enforce the app''s Content Security Policy', 'next', 'Audit', 'It is report-only today; the csp-enforce-public branch exists.', 22);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-sitemap', 'Publish a sitemap for the app', 'next', 'Audit', '', 23);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-previews', 'Add canonical addresses and link previews', 'next', 'Audit', 'Low priority; every page lacks them.', 24);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-egress', 'Review refused egress requests each month', 'next', 'Google Cloud', 'A BigQuery query in docs/gcp-observability.md shows which hosts visitors ask for.', 25);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('l-failover', 'Put the failover Worker on the live route', 'later', 'Website', 'Written and tested. Use fail-open routing; test on a separate address first.', 26);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('l-vault', 'Personal-data vault with grants', 'later', 'Privacy', 'Not started. Personal data stays on the owner''s computer until then.', 27);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('p-signups', 'Open sign-ups', 'paused', 'RabbitOS', 'Stays off in Supabase until the live checks pass.', 28);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('p-k8s', 'Kubernetes cluster', 'paused', 'Google Cloud', 'Optional. Cloud Run covers the needs today; Setup-GcpGke.ps1 is ready.', 29);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-research-tools', 'Research tools in the hub: research_sources and research_search', 'done', 'Research', 'Code and tests are done (PubMed, Europe PMC, ClinicalTrials.gov, openFDA). Live after the hub is redeployed.', 30);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-wallet-anchor', 'Bitcoin anchoring and a hardware-key donation wallet', 'done', 'Chain', 'Anchors every 6 hours through OpenTimestamps (Bitcoin). A hardware-key wallet exists; public donations are paused and the pages do not show it.', 31);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-miner-cloud', 'Cloud miner running nightly', 'done', 'Chain', 'Secrets stored, job deployed, first run mined block 3; the app, the bucket and your PC agree.', 32);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-backup-cloud', 'Cloud backup job running nightly', 'done', 'Google Cloud', 'Supabase dump plus D1, KV and R2, compared with the local backup.', 33);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-hub-redeployed', 'Hub redeployed with research_search, hub_help and anchor_status', 'done', 'Assistants', 'Self-test 15 of 15.', 34);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-security', 'Security hardening: service accounts, audit logs, TLS, firewall, Secure Boot', 'done', 'Google Cloud', 'See docs/security-hardening.md. App content-security-policy enforcement ships with the next app deploy.', 35);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-rfnexus', 'RF Nexus preview moved to Google Cloud', 'done', 'Google Cloud', 'Cloud Run, no roles, no secrets; the Cloudflare Worker was deleted.', 36);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-ops-log', 'Operations log kept for every change to this setup', 'done', 'Operations', 'docs/ops-log.md, one entry with how it was checked and how to undo it.', 37);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-vault-gcs', 'Obsidian vault copied to a private Google Cloud bucket, hourly', 'done', 'Google Cloud', '2,383 files, 264 MB. Local/EEG and the PC-folder view are left out on purpose.', 38);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-miner-job', 'Cloud miner, adopt and research loop written and tested', 'done', 'Chain', 'Scheduled sync (30 min) and task worker (5 min) run on your PC; the cloud miner waits for its secret step.', 39);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-backup-job', 'Cloud backup job written and tested', 'done', 'Google Cloud', 'Supabase dump and Cloudflare D1, KV, R2 as a Cloud Run job; offline tests pass.', 40);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-help-catalog', 'Every platform command recorded in the catalog, with hub_help for workers', 'done', 'Assistants', '234 commands (36 guest, 198 owner): Google Cloud setup with previews, hub keys, tests, wallet and anchoring, read-only hub calls. hub_help explains services, tools, shells, agents and troubleshooting. Live in the hub.', 41);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-withdraw', 'Withdrawal tool for the wallet (tested, guarded)', 'done', 'Chain', 'Signs through Cloud KMS; allowlist, limits and retyped confirmation. Tested against EIP-155 and BIP143 vectors and the real key.', 42);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-wallet-test', 'Test the wallet with a small real amount, then decide the recovery plan', 'waiting', 'You', 'Follow docs/wallet.md. There is no seed phrase; decide how you will limit the one-copy risk.', 43);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-wallet-recovery', 'Wallet recovery protections and a receiving record on Google Cloud', 'done', 'Chain', 'Project lien, 30-day key destroy delay, email alert on any key change, and a watcher that records and announces what arrives. The key cannot be exported, so the rest of the plan is: keep a small float and sweep to a wallet you hold. Add a second Owner (your decision). See docs/wallet.md.', 44);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('p-second-owner', 'Add a second project Owner for the wallet key', 'paused', 'Chain', 'Not yet, by the owner''s choice. Until then there is one Owner; the lien, the 30-day destroy delay and the key-change alert are the protection. The wallet is treated as a receiving account only.', 45);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-vault-inbound', 'Cloud-to-local path for vault objects (inbox pull)', 'next', 'Operations', 'Today every vault path is one-way. Options in docs/vault-pathways.md: a PC task that pulls new files from an inbox/ prefix, optionally event-driven through Pub/Sub. Waiting for the owner to say which events and objects they mean.', 46);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-vault-pathways', 'Vault pathways mapped and tested (2026-10-16)', 'done', 'Operations', 'docs/vault-pathways.md: vault to GitHub, to the Google Cloud bucket and to search verified end to end; the PC GitHub sync was repaired.', 47);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-hf-connected', 'Hugging Face connected to the platform (2026-10-16)', 'done', 'AI', 'docs/huggingface.md: Space and model on the map and the hub, nightly backup of buckets and datasets to Google Cloud, Space checked by the pathway check.', 48);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-agents-registry', 'Agents listed in the Google Cloud Agent Registry (2026-10-16)', 'done', 'AI', 'Research Agent (A2A) deployed on Cloud Run; it and the Hub MCP registered. docs/agents.md lists every agent and how to deploy it. PC agents stay local on purpose.', 49);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-task-worker-cloud', 'Task worker moved into Google Cloud (2026-10-16)', 'done', 'AI', 'Cloud Run job every 5 minutes, public sources only. The PC task can stay as a second worker or be disabled.', 50);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-explorers-cloud', 'Move the research explorers to Google Cloud', 'next', 'AI', 'They keep a topic queue and corpus in local files, so the state has to live in the app or a bucket first, and PC and cloud must not overwrite each other. Needs a design decision.', 51);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-vault-mirror', 'Create a read-only GitHub token and run Setup-GcpVaultMirrorSecrets.ps1, then Setup-GcpVaultMirror.ps1', 'waiting', 'You', 'Fine-grained token, only the vault repository, Contents: read-only. You paste it into the script (hidden); Claude never sees it.', 52);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-vault-github-migrated', 'Vault repository moved to the main GitHub account (2026-10-16)', 'done', 'Operations', 'therealsickonechase-bit/obsidian-rabbitos-vault, private, full history. The PC sync task pushes there; the Obsidian plugin still points at its old account until you change its settings.', 53);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-donations-open', 'Donations open on rabbitsoftware.io and in the app (2026-10-16)', 'done', 'Chain', 'Front page block, /donate, wallet.json and the app show the addresses with open-in-wallet links. Not yet promoted: do the small wallet test and decide the legal and tax stance first.', 54);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('p-eth-xrpl', 'Ethereum and XRP Ledger anchoring', 'paused', 'Chain', 'Built and deployed with its own key. Fund about 0.003 ETH and 2 XRP at the addresses in anchors/chains.json, then resume the Scheduler job rabbit-anchor-chains-6h.', 55);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-btc-confirm', 'First Bitcoin anchor confirmed (block 971631)', 'done', 'Chain', 'The scheduled job upgraded the proof by itself at 01:00 UTC. Checked independently: the document hash matches and the proof ends at the Bitcoin block merkle root.', 56);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-live-more', 'Live search for NIH RePORTER and ClinVar', 'next', 'Research', 'RePORTER needs a POST; ClinVar needs its own response shape. Both are already used by the owner''s agents.', 57);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-ingest-proposals', 'Let a live search propose an ingest task', 'next', 'Research', 'The tasks page already takes proposals; a person approves before the owner''s agents fetch and store anything.', 58);
